        "groupId": "group_III",
        "groupName": "Kết quả thực hiện nhiệm vụ",
        "subGroup": "A",
        "order": 2,
        "content": "Khả năng đáp ứng nhiệm vụ thường xuyên và nhiệm vụ đột xuất; chủ động xử lý công việc trong phạm vi trách nhiệm.",
