        "groupId": "group_III",
        "groupName": "Kết quả thực hiện nhiệm vụ",
        "subGroup": "A",
        "order": 3,
        "content": "Sử dụng thành thạo phần mềm quản lý, hồ sơ điện tử, công cụ CNTT và công cụ số phục vụ công việc.",
        "maxScore": 2,
