          "groupName": "Chính trị tư tưởng, đạo đức lối sống",
          "order": 7,
          "content": "Đoàn kết, tôn trọng, hỗ trợ đồng nghiệp; phối hợp xây dựng tổ chuyên môn và nhà trường.",
