          "groupName": "Tác phong, lề lối làm việc, ý thức tổ chức kỷ luật",
          "order": 2,
          "content": "Lập kế hoạch công việc khoa học; thực hiện nhiệm vụ theo thứ tự ưu tiên; lưu trữ hồ sơ, minh chứng đầy đủ.",
          "maxScore": 1.5,
