          "groupName": "Chính trị tư tưởng, đạo đức lối sống",
          "order": 6,
          "content": "Trung thực, khiêm tốn, chân thành, chuẩn mực; giữ gìn phẩm chất, uy tín và danh dự nhà giáo.",
