          "groupId": "group_II",
          "groupName": "Tác phong, lề lối làm việc, ý thức tổ chức kỷ luật",
          "order": 7,
          "content": "Thực hiện đầy đủ, đúng hạn các báo cáo; cung cấp thông tin chính xác, khách quan; cập nhật dữ liệu trên các phần mềm được giao.",
