          "code": "8",
          "groupId": "group_III",
          "groupName": "Kết quả thực hiện nhiệm vụ",
          "subGroup": "B",
          "order": 12,
          "content": "Tham gia dự giờ, thao giảng, nghiên cứu bài học; tiếp thu và thực hiện điều chỉnh sau góp ý chuyên môn.",
