          "groupId": "group_I",
          "groupName": "Chính trị tư tưởng, đạo đức lối sống",
          "order": 2,
          "content": "Có lập trường, bản lĩnh chính trị vững vàng; có ý thức trách nhiệm, không dao động trước khó khăn; thực hiện nghiêm nhiệm vụ được giao.",
