          "groupName": "Chính trị tư tưởng, đạo đức lối sống",
          "order": 3,
          "content": "Đặt lợi ích của tập thể, học sinh và nhà trường lên trên lợi ích cá nhân; có tinh thần trách nhiệm với chất lượng giáo dục.",
